import { argon2Hasher } from '../src/hashers/argon2.js';
import { createAuth } from '../src/index.js';
import { memoryStore } from '../src/stores/memory.js';

const auth = createAuth({
  store: memoryStore(),
  hasher: argon2Hasher(),
  requireEmailVerification: false,
});
const creds = { email: 'ann@example.com', password: 'correct horse battery staple' };

await auth.signUp(creds);
const { token, user } = await auth.signIn(creds);
console.log(
  'signed in:',
  user.email,
  '| session valid:',
  (await auth.getSessionFromToken(token)) !== null,
);
